export function firstItemId(items) {
  return items[0].id;
}

export function lastItemId(items) {
  if (!Array.isArray(items) || items.length === 0) {
    throw new RangeError('items must be a non-empty array');
  }
  return items[items.length - 1].id;
}

export function clampLimit(limit) {
  return Math.min(100, Math.max(1, Math.trunc(Number(limit) || 1)));
}

files.test/items.test.mjs:
import test from 'node:test';
import assert from 'node:assert/strict';
import { firstItemId, lastItemId, clampLimit } from '../src/items.mjs';

test('first and last ids', () => {
  assert.equal(firstItemId([{ id: 'a' }, { id: 'b' }]), 'a');
  assert.equal(lastItemId([{ id: 'a' }, { id: 'b' }]), 'b');
});

test('clampLimit bounds input', () => {
  assert.equal(clampLimit(1e308), 100);
});

